(* [comment removed for export] *)
Lemma hz_F2 : forall (LF : list fframe) (spa ff fp lo shi : Z)
    (sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  0 <= spa -> spa + 96 <= 2^64 -> fresh_frame H LF 4 ff fp ->
  rw_cells asegs m (Z.shiftr ff 3 + 2147450880) hz_sh3 ->
  mem_inv asegs m -> as_RFS H ((4, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  evt asegs (fun ms' => exists m',
      ms' = MS (mkR (Z_to_bv 64 P_HZ_RET_SDT) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 (spa + 16)) a1 a2 a3 a4 a5 a6 a7
                    (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) s4 s5 s6 s7 s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_A_STREAM_DTOR) fc None m' (seg_rom asegs)
      /\ munch (hz_F2_W ff) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ rw_cells asegs m' (Z.shiftr ff 3 + 2147450880) hz_sh2
      /\ as_RFS H ((4, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi)
    (MS (mkR (Z_to_bv 64 P_HZ_RET_PDT) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) s4 s5 s6 s7 s8 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
